Here is a PL/pgSQL function that calculates a priority index for artifacts. The function takes in the artifact's conservation status, historical significance rating, conservation priority score, and conservation treatment status as parameters and returns the corresponding CPI value.

```sql
CREATE OR REPLACE FUNCTION calculate_cpi(
    p_conserve_status VARCHAR,
    p_hist_sign_rating SMALLINT,
    p_conserve_priority_score SMALLINT,
    p_conserve_treat_status VARCHAR
)
RETURNS DECIMAL AS $
DECLARE
    cpi DECIMAL;
BEGIN
    -- Assign weights to conservation status
    CASE p_conserve_status
        WHEN 'Excellent' THEN cpi := 1.0;
        WHEN 'Good' THEN cpi := 2.0;
        WHEN 'Fair' THEN cpi := 3.0;
        WHEN 'Poor' THEN cpi := 4.0;
        WHEN 'Critical' THEN cpi := 5.0;
        ELSE cpi := 0.0;
    END CASE;

    -- Incorporate historical significance rating
    cpi := cpi + (p_hist_sign_rating * 0.1);

    -- Incorporate conservation priority score
    cpi := cpi + (p_conserve_priority_score * 0.01);

    -- Adjust CPI based on conservation treatment status
    CASE p_conserve_treat_status
        WHEN 'In Progress' THEN cpi := cpi * 1.2;
        WHEN 'Not Required' THEN cpi := cpi * 0.8;
        WHEN 'Scheduled' THEN cpi := cpi * 1.1;
        ELSE cpi := cpi;
    END CASE;

    RETURN cpi;
END;
$ LANGUAGE plpgsql;
```

